css:
/* 把 above-composer 槽位变成浮层：不占页面网格，没有上传时不显示。
   这是"用 CSS 就能做到"的证明 —— 加控件不需要改 index.html。 */
#slot-above-composer {
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  /* 贴在输入区上方。实测桌面：输入框顶到视口底 109px（输入框 62 + 任务栏
     20 + 状态栏 26 + 边距），所以 bottom:109px 正好让浮层底边落在输入框
     上沿。写死是因为这里的布局是固定的几行，用 calc 猜反而会差几像素。 */
  bottom: 109px;
  width: min(560px, calc(100vw - 32px));
  z-index: 45;
  pointer-events: none;
}
/* 手机输入区更高（44px 触控），单独给一个 bottom。 */
@media (max-width: 860px) {
  #slot-above-composer {
    bottom: 132px;
    width: calc(100vw - 20px);
  }
}
#slot-above-composer:empty { display: none; }
#slot-above-composer > * { pointer-events: auto; }

.ub {
  background: var(--card);
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  box-shadow: 0 6px 24px color-mix(in srgb, #000 18%, transparent);
  padding: 10px 12px 11px;
  font-size: 11.5px;
}
.ub[hidden] { display: none; }
.ub-row { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
.ub-name {
  flex: 1 1 auto; min-width: 0;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--mono); font-size: 11px;
}
.ub-pct {
  flex: 0 0 auto; color: var(--accent); font-weight: 600;
  font-variant-numeric: tabular-nums; min-width: 4ch; text-align: right;
}
.ub-x {
  flex: 0 0 auto; border: 0; background: none; cursor: pointer;
  color: var(--dim); font-size: 16px; line-height: 1; padding: 0 2px;
}
.ub-x:hover { color: var(--bad); }
.ub-track {
  height: 5px; border-radius: 3px; overflow: hidden;
  background: var(--panel); border: 1px solid var(--line);
}
.ub-fill { height: 100%; width: 0%; background: var(--accent); transition: width .18s ease-out; }
.ub-bytes { margin-top: 5px; font-size: 10.5px; color: var(--dim);
  font-variant-numeric: tabular-nums; }

panels.script:
// 上传进度浮层。
//
// 它挂在 above-composer 槽位上，用 CSS 把这个槽位变成固定在输入框上方的
// 浮层 —— 所以它既不吃掉页面的一行网格，也不在没有上传时占地方。
// 页面本身不知道这个控件的存在：它只把进度作为事件发出来。
let bar = null;

function ensure() {
  if (bar) return bar;
  bar = document.createElement("div");
  bar.className = "ub";
  bar.hidden = true;
  bar.innerHTML =
    '<div class="ub-row">' +
      '<span class="ub-name"></span>' +
      '<span class="ub-pct"></span>' +
      '<button type="button" class="ub-x" title="取消">×</button>' +
    '</div>' +
    '<div class="ub-track"><div class="ub-fill"></div></div>' +
    '<div class="ub-bytes"></div>';
  // 普通面板没有 typeDocument 传入的 host，内容直接进 body。
  document.body.append(bar);
  return bar;
}

function fmt(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(0) + " KB";
  return (bytes / (1024 * 1024)).toFixed(1) + " MB";
}

function reportHeight() {
  // 面板高度由宿主按消息设置。内容变化后必须重报一次，否则宿主还按上一次
  // （常常是 hidden 时的 0 或初始 40px）的高度画，内容就被压没了。
  const h = Math.ceil(document.body.getBoundingClientRect().height +
    (bar && !bar.hidden ? bar.getBoundingClientRect().height : 0));
  parent.postMessage({
    ngu: "panel", panelId: "upload-progress", requestId: null,
    cmd: "panel:resize", args: { height: h },
  }, "*");
}

function show(p) {
  const el = ensure();
  if (p.done) {
    el.hidden = true;
    reportHeight();
    return;
  }
  el.hidden = false;
  el.querySelector(".ub-name").textContent = p.label || "";
  el.querySelector(".ub-pct").textContent = (p.percent || 0) + "%";
  el.querySelector(".ub-fill").style.width = (p.percent || 0) + "%";
  el.querySelector(".ub-bytes").textContent =
    fmt(p.loaded || 0) + " / " + fmt(p.total || 0);
  reportHeight();
}

// 进度从宿主转进来：面板是沙箱文档，读不到主页面的状态。
// 宿主发的是 { ngu: "panel-event", event: { ev, progress } }。
window.addEventListener("message", (event) => {
  const data = event.data;
  if (!data || data.ngu !== "panel-event") return;
  const ev = data.event;
  if (!ev || ev.ev !== "upload-progress") return;
  show(ev.progress || {});
});

// 面板是独立文档：主页面的样式（包括这个包注入的 CSS）进不来。
// 所以样式自己带一份，用主页面同样的 token 值。
const style = document.createElement("style");
style.textContent = [
  ".ub{background:#faf6ee;border:1px solid #bfb3a0;border-radius:12px;",
  "padding:10px 12px 11px;font:11.5px/1.4 system-ui,sans-serif;color:#3a2e24;",
  "box-shadow:0 6px 24px rgba(0,0,0,.18);}",
  ".ub[hidden]{display:none;}",
  ".ub-row{display:flex;align-items:center;gap:10px;margin-bottom:7px;}",
  ".ub-name{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;",
  "white-space:nowrap;font-family:ui-monospace,Consolas,monospace;font-size:11px;}",
  ".ub-pct{flex:0 0 auto;color:#b4632a;font-weight:600;",
  "font-variant-numeric:tabular-nums;min-width:4ch;text-align:right;}",
  ".ub-x{flex:0 0 auto;border:0;background:none;cursor:pointer;",
  "color:#7d7264;font-size:16px;line-height:1;padding:0 2px;}",
  ".ub-track{height:5px;border-radius:3px;overflow:hidden;",
  "background:#e9e3d7;border:1px solid #d5cbb9;}",
  ".ub-fill{height:100%;width:0%;background:#b4632a;transition:width .18s ease-out;}",
  ".ub-bytes{margin-top:5px;font-size:10.5px;color:#7d7264;",
  "font-variant-numeric:tabular-nums;}",
].join("");
document.head.append(style);

// 首屏就建好，免得第一次上传时才发现容器不存在。
ensure();
